from mosslight.courier import *
def obs(p): return json.dumps(observations(p), sort_keys=True)
bad=0
for trial in range(300):
    rng=random.Random(trial)
    peers=[new_packet(n) for n in 'abc']
    history=[]
    for step in range(rng.randint(3,15)):
        i=rng.randrange(3); p=peers[i]
        r=rng.random(); rec=rng.choice(['r1','r2','r3'])
        if r<.45: put(p, rec, {'text':rng.choice(['x','y','z','X'])})
        elif r<.55: remove(p, rec)
        elif r<.8:
            j=rng.randrange(3)
            if j!=i:
                src=peers[j]
                if rng.random()<.3: src=project(src,[rec])
                if rng.random()<.3: src=checkpoint(src)
                peers[i]=merge(p, src)
        else:
            peers[i]=checkpoint(p)
        history.append(copy.deepcopy(peers))
    a,b,c=peers
    m1=merge(merge(a,b),c); m2=merge(c,merge(b,a)); m3=merge(merge(c,a),b)
    if not (obs(m1)==obs(m2)==obs(m3)): bad+=1; print('assoc/comm', trial)
    if obs(merge(m1,m1))!=obs(m1): bad+=1; print('idem', trial)
    if obs(merge(checkpoint(m1), a))!=obs(m1) or obs(merge(a,checkpoint(m1)))!=obs(m1): bad+=1; print('ckpt', trial)
    # old packets don't resurrect
    old=history[0][0]
    if obs(merge(m1,old))!=obs(m1): bad+=1; print('old', trial)
    # projection of full merge into full is no-op
    if obs(merge(m1, project(m1,['r1'])))!=obs(m1): bad+=1; print('proj', trial)
print('bad', bad)
"

